/** Where a member's media comes from: its participant on a room, null while it has none. */
export type ParticipantSource<P extends Participant = Participant> = {
    participant: P;
    room: LivekitRoom;
} | null;
/**
 * A member's media from its participant. The only place, with
 * `LivekitMediaTrack`, that reads a LiveKit participant; everything above
 * sees tracks and behaviors.
 */
export declare function createLivekitMemberMedia(scope: ObservableScope, source$: Behavior<ParticipantSource>, encryptionSystem: EncryptionSystem): MemberMedia;
export declare function createLocalLivekitMemberMedia(scope: ObservableScope, source$: Behavior<ParticipantSource<LocalParticipant>>, encryptionSystem: EncryptionSystem, setEnabled: (source: MediaSource, enabled: boolean) => Promise<boolean>): LocalMemberMedia;
